INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist traceroute nur für IPv6-Netze geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch IPv4 unterstützt"}, {"text": "Ja", "correct": false, "because": "Protokollunabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hauptaufgabe hat traceroute?', 3, '[{"text": "Routennachverfolgung", "correct": true, "because": "Zeigt Pfad zum Ziel"}, {"text": "IP-Zuweisung", "correct": false, "because": "DHCP-Aufgabe"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen liefert traceroute?', 5, '[{"text": "Hop-by-Hop-Pfad", "correct": true, "because": "Listet Router auf"}, {"text": "Latenz pro Hop", "correct": true, "because": "Misst Verzögerung"}, {"text": "Bandbreitengrenze", "correct": false, "because": "Nicht gemessen"}, {"text": "DNS-Server", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Traceroute nutzt ICMP. b) Es zeigt nur lokale Netze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pfad geht über Netze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei traceroute?', 4, '[{"text": "Hop-Adressen", "correct": false, "because": "Definiert Pfad"}, {"text": "Latenzwerte", "correct": false, "because": "Zeigt Verzögerung"}, {"text": "Datenpayload", "correct": true, "because": "Nur Pfadanalyse"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob traceroute immer das Ziel erreicht?', 2, '[{"text": "Nein", "correct": true, "because": "Blockaden möglich"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll nutzt traceroute standardmäßig?', 3, '[{"text": "ICMP", "correct": true, "because": "Für Pfadnachverfolgung"}, {"text": "TCP", "correct": false, "because": "Nicht Standard"}, {"text": "HTTP", "correct": false, "because": "Anwendungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme kann traceroute aufdecken?', 5, '[{"text": "Routing-Schleifen", "correct": true, "because": "Time Exceeded"}, {"text": "Nicht erreichbare Hops", "correct": true, "because": "Timeouts"}, {"text": "IP-Konflikte", "correct": false, "because": "Andere Ebene"}, {"text": "Datenkompression", "correct": false, "because": "Nicht analysiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Traceroute zeigt den Pfad. b) Es misst nur Latenz. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Latenz und Pfad"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für traceroute?', 4, '[{"text": "Ziel-IP", "correct": false, "because": "Definiert Endpunkt"}, {"text": "ICMP", "correct": false, "because": "Kernprotokoll"}, {"text": "Webserver", "correct": true, "because": "Nicht Pfad-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt traceroute die Bandbreite?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Pfad und Latenz"}, {"text": "Ja", "correct": false, "because": "Andere Tools nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ergebnis zeigt das Ziel?', 4, '[{"text": "Echo Reply vom Ziel", "correct": true, "because": "Ziel erreicht"}, {"text": "Time Exceeded", "correct": false, "because": "Hop-Limit"}, {"text": "Destination Unreachable", "correct": false, "because": "Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass traceroute nur lokale Router zeigt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Pfad bis Ziel"}, {"text": "Ja", "correct": false, "because": "Missverständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei traceroute?', 3, '[{"text": "Hop-Liste", "correct": true, "because": "Zeigt Routenverlauf"}, {"text": "DNS-Namen", "correct": false, "because": "Optional"}, {"text": "Paketgröße", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Traceroute nutzt TTL. b) Es ersetzt ping.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ping bleibt eigenständig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet traceroute?', 5, '[{"text": "Pfadanalyse", "correct": true, "because": "Hop-by-Hop"}, {"text": "Fehlererkennung", "correct": true, "because": "Timeouts sichtbar"}, {"text": "Datenübertragung", "correct": false, "because": "Nur Diagnose"}, {"text": "IP-Konfiguration", "correct": false, "because": "Andere Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei traceroute unwichtig?', 3, '[{"text": "Hop-Adressen", "correct": false, "because": "Definiert Pfad"}, {"text": "Latenz", "correct": false, "because": "Zeigt Verzögerung"}, {"text": "HTTP-Status", "correct": true, "because": "Anwendungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt traceroute nur ICMP?', 3, '[{"text": "Nein", "correct": true, "because": "Auch UDP möglich"}, {"text": "Ja", "correct": false, "because": "Variiert je nach Tool"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob traceroute Firewall-Probleme zeigt?', 2, '[{"text": "Ja", "correct": true, "because": "Timeouts bei Blockade"}, {"text": "Nein", "correct": false, "because": "Indirekt sichtbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Antwort zeigt einen Routing-Fehler?', 4, '[{"text": "Time Exceeded", "correct": true, "because": "Hop-Limit überschritten"}, {"text": "Echo Reply", "correct": false, "because": "Erfolg"}, {"text": "Neighbor Advertisement", "correct": false, "because": "NDP-spezifisch"}]');
